import java.util.ArrayList;
import java.util.List;

public class OnlineStockSpanTest {

    @Test
    public void testNext_SinglePrice() {
        OnlineStockSpan instance = new OnlineStockSpan();
        int price = 1;
        int[] prices = {1};
        int[] expectedSpans = {0};
        when(instance.next(price)).thenReturn(1);
        int actualSpans = instance.calculateSpans(prices);
        assertEquals(expectedSpans[0], actualSpans);
    }

    @Test
    public void testNext_MultiplePrices() {
        OnlineStockSpan instance = new OnlineStockSpan();
        int price1 = 2;
        int price2 = 3;
        List<Integer> prices = new ArrayList<>();
        prices.add(price1);
        prices.add(price2);
        instance.next(price1);
        instance.next(price2);
        when(instance.next(price1)).thenReturn(0);
        when(instance.next(price2)).thenReturn(0);
        int[] actualSpans = instance.calculateSpans(prices);
        assertArrayEquals(new int[]{price1, price2}, actualSpans);
    }

